/// <summary>
/// Base class for PricingAttribute table <c>EcoResProductCategory</c>
/// </summary>
internal abstract class GUPPricingAttributeEcoResProductCategory extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{
}

Method.Source:
protected EcoResProductCategory getTableRecord(Common _pricingObject)
{
    EcoResProductCategory ecoResProductCategory;
    SalesLine salesLine = _pricingObject as SalesLine;

    if (salesLine.ItemId)
    {
        InventTable inventTable;
        EcoResCategoryHierarchyRole ecoResCategoryHierarchyRole;

        container hierarchyRolesForPricing = GUPCategoryHierarchyLookupHelper::getHierarchyRolesForPricing();

        while select ecoResCategoryHierarchyRole
            join ecoResProductCategory
                where ecoResProductCategory.CategoryHierarchy == ecoResCategoryHierarchyRole.CategoryHierarchy
            exists join inventTable
                where inventTable.Product == ecoResProductCategory.Product
                    && inventTable.ItemId == salesLine.ItemId
        {
            int         idx = 0;
            int         len = conLen(hierarchyRolesForPricing);

            // if product category record is under supported category hierarchy roles.
            while (idx < len)
            {
                idx += 1;

                EcoResCategoryNamedHierarchyRole tmp = conPeek(hierarchyRolesForPricing, idx);
                if (tmp == ecoResCategoryHierarchyRole.NamedCategoryHierarchyRole)
                {
                    return ecoResProductCategory;
                }
            }
        }
    }

    return ecoResProductCategory;
}

protected container getEcoResCategoryAndHierarchy(Common _pricingObject)
{
    container ecoResCategoryRecIdCon;
    container ecoResCategoryHierarchyCon;
    EcoResProductCategory ecoResProductCategory;
    SalesLine salesLine = _pricingObject as SalesLine;

    if (salesLine.ItemId)
    {
        InventTable inventTable;
        EcoResCategoryHierarchyRole ecoResCategoryHierarchyRole;

        container hierarchyRolesForPricing = GUPCategoryHierarchyLookupHelper::getHierarchyRolesForPricing();

        while select ecoResCategoryHierarchyRole
            join ecoResProductCategory
                where ecoResProductCategory.CategoryHierarchy == ecoResCategoryHierarchyRole.CategoryHierarchy
            exists join inventTable
                where inventTable.Product == ecoResProductCategory.Product
                    && inventTable.ItemId == salesLine.ItemId
        {
            int         idx = 0;
            int         len = conLen(hierarchyRolesForPricing);

            // if product category record is under supported category hierarchy roles.
            while (idx < len)
            {
                idx += 1;

                EcoResCategoryNamedHierarchyRole tmp = conPeek(hierarchyRolesForPricing, idx);
                if (tmp == ecoResCategoryHierarchyRole.NamedCategoryHierarchyRole)
                {
                    ecoResCategoryRecIdCon += ecoResProductCategory.Category;
                    ecoResCategoryHierarchyCon += ecoResProductCategory.CategoryHierarchy;
                }
            }
        }
    }

    return [ecoResCategoryRecIdCon, ecoResCategoryHierarchyCon];
}

protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
{
    QueryBuildDataSource qbds, qbdsRoot;
    QueryBuildDataSource qbdsExistsJoin;

    if (_qbdsMap && _qbdsMap.exists(tableStr(InventTable)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(InventTable));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(InventTable));
        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(InventTable), qbdsRoot);
        }
    }

    if (_qbdsMap && _qbdsMap.exists(this.getQueryBuilderDatasourceIdentifier()))
    {
        qbds = _qbdsMap.lookup(this.getQueryBuilderDatasourceIdentifier());
    }
    else
    {
        qbds = qbdsRoot.addDataSource(tableNum(EcoResProductCategory));
        qbds.addLink(fieldNum(InventTable, Product), fieldNum(EcoResProductCategory, Product));
        qbds.joinMode(JoinMode::InnerJoin);

        qbds = qbds.addDataSource(tableNum(EcoResCategory));
        qbds.addLink(fieldNum(EcoResProductCategory, Category), fieldNum(EcoResCategory, RecId));
        qbds.joinMode(JoinMode::InnerJoin);

        qbdsExistsJoin = qbds.addDataSource(tableNum(EcoResCategoryHierarchyRole));
        qbdsExistsJoin.addLink(fieldNum(EcoResCategory, CategoryHierarchy), fieldNum(EcoResCategoryHierarchyRole, CategoryHierarchy));
        qbdsExistsJoin.joinMode(JoinMode::ExistsJoin);

        if (_qbdsMap)
        {
            _qbdsMap.insert(this.getQueryBuilderDatasourceIdentifier(), qbds);
        }
    }

    return qbds;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
    this.setQueryBuildDatasourceRange(qbds, _value);

    return _query;
}

public GUPPricingAttributeTableFieldPath getPath()
{
    return strFmt('%1#%2_%3$%4#%5_%6$%7#%8',
        tableStr(SalesLine),
        tableStr(InventTable),
        fieldStr(SalesLine, ItemId),
        fieldStr(InventTable, ItemId),
        tableStr(EcoResProductCategory),
        fieldStr(InventTable, Product),
        fieldStr(EcoResProductCategory, Product),
        this.getAttributeFieldIdentifier());
}
